import{LOKTAK_DATA}from"./loktak-data.js";function initTheme(){const t=document.getElementById("theme-toggle");t&&t.addEventListener("click",()=>{document.body.classList.toggle("light-theme");const e=document.body.classList.contains("light-theme");localStorage.setItem("theme",e?"light":"dark"),t.textContent=e?"🌙":"☀️"})}function initNavbar(){const t=document.getElementById("menu-toggle"),e=document.getElementById("nav-menu");t&&e&&t.addEventListener("click",()=>{const n="true"===t.getAttribute("aria-expanded");t.setAttribute("aria-expanded",!n),e.classList.toggle("active")})}function renderStats(){const t=document.getElementById("stats-grid");t&&LOKTAK_DATA.stats&&(t.innerHTML=LOKTAK_DATA.stats.map(t=>`\n        <div class="stat-card">\n            <span class="stat-icon">${t.icon}</span>\n            <div class="stat-value">${t.value}</div>\n            <div class="stat-label">${t.label}</div>\n        </div>\n    `).join(""))}function renderHistory(){const t=document.getElementById("history-title"),e=document.getElementById("history-content");t&&(t.textContent=LOKTAK_DATA.history.title),e&&(e.textContent=LOKTAK_DATA.history.content)}function renderPhumdis(){const t=document.getElementById("phumdis-title"),e=document.getElementById("phumdis-content");t&&(t.textContent=LOKTAK_DATA.phumdis.title),e&&(e.textContent=LOKTAK_DATA.phumdis.content)}function renderSangai(){const t=document.getElementById("keibul-content"),e=document.getElementById("keibul-highlights");t&&(t.textContent=LOKTAK_DATA.keibulLamjao.content),e&&LOKTAK_DATA.keibulLamjao.highlights&&(e.innerHTML=LOKTAK_DATA.keibulLamjao.highlights.map(t=>`<div class="hl-item">🦌 ${t}</div>`).join(""))}function renderBiodiversity(){const t=document.getElementById("ramsar-title"),e=document.getElementById("ramsar-content"),n=document.getElementById("bio-title"),o=document.getElementById("bio-content");t&&(t.textContent=LOKTAK_DATA.ramsarSite.title),e&&(e.textContent=LOKTAK_DATA.ramsarSite.content),n&&(n.textContent=LOKTAK_DATA.biodiversity.title),o&&(o.textContent=LOKTAK_DATA.biodiversity.content)}function renderCommunity(){const t=document.getElementById("community-content");t&&(t.textContent=LOKTAK_DATA.localCommunities.content)}function renderMapHotspots(){const t=document.getElementById("hotspots-list");t&&LOKTAK_DATA.hotspots&&(t.innerHTML=LOKTAK_DATA.hotspots.map((t,e)=>`\n        <button class="spot-btn ${0===e?"active":""}" data-id="${t.id}">\n            <span class="spot-name">${t.name}</span>\n        </button>\n    `).join(""),showHotspotDetail(LOKTAK_DATA.hotspots[0]),t.addEventListener("click",t=>{const e=t.target.closest(".spot-btn");if(!e)return;const n=e.getAttribute("data-id"),o=LOKTAK_DATA.hotspots.find(t=>t.id===n);document.querySelectorAll(".spot-btn").forEach(t=>t.classList.remove("active")),e.classList.add("active"),o&&showHotspotDetail(o)}))}function showHotspotDetail(t){const e=document.getElementById("hotspot-detail");e&&(e.innerHTML=`\n        <h3 style="margin: 0 0 0.5rem; color: #34d399; font-size: 1.5rem;">${t.name}</h3>\n        <p style="color: var(--loktak-text-sub); line-height: 1.6; margin-bottom: 1.25rem;">${t.desc}</p>\n        <div style="font-family: monospace; font-size: 0.85rem; color: #94a3b8; background: rgba(0,0,0,0.2); padding: 0.5rem 0.85rem; border-radius: 0.5rem;">Coordinates: ${t.lat}° N, ${t.lng}° E</div>\n    `)}function renderGallery(){const t=document.getElementById("gallery-grid");t&&LOKTAK_DATA.gallery&&(t.innerHTML=LOKTAK_DATA.gallery.map(t=>`\n        <div class="gallery-card">\n            <img src="${t.url}" alt="${t.title}" loading="lazy" />\n            <div class="gallery-info">\n                <h4>${t.title}</h4>\n                <p>${t.caption}</p>\n            </div>\n        </div>\n    `).join(""))}function renderFacts(){const t=document.getElementById("facts-grid");t&&LOKTAK_DATA.facts&&(t.innerHTML=LOKTAK_DATA.facts.map(t=>`<div class="trivia-box">💡 ${t}</div>`).join(""))}document.addEventListener("DOMContentLoaded",()=>{initTheme(),initNavbar(),renderStats(),renderHistory(),renderPhumdis(),renderSangai(),renderBiodiversity(),renderCommunity(),renderMapHotspots(),renderGallery(),renderFacts()});